cd /tmp/ross-main && cat > /tmp/check_complete.py <<'EOF'
import subprocess, re, os, glob

branches = ["rachel","monica","phoebe","joey","chandler","ross"]
def run(*a):
    return subprocess.run(a, capture_output=True, text=True, check=True).stdout

all_commits = {}
for b in branches:
    out = subprocess.run(["git","log","--format=%H%x01%cI%x01%B%x02","origin/friend/"+b],
                         capture_output=True,text=True,check=True).stdout
    for rec in out.split("\x02"):
        rec = rec.strip("\n")
        if not rec.strip(): continue
        parts = rec.split("\x01")
        if len(parts) < 3: 
            continue
        sha, ci, body = parts[0].strip(), parts[1], parts[2]
        if "Friend-Message: 1" in body:
            all_commits[sha] = (b, ci, body)

filed = {}
for f in glob.glob("S*/E*.md"):
    txt = open(f).read()
    for m in re.finditer(r"Source: friend/([a-z]+) @ ([0-9a-f]{40})", txt):
        filed[m.group(2)] = f

missing = {s:v for s,v in all_commits.items() if s not in filed}
print("total friend messages:", len(all_commits), "filed:", len(filed), "missing:", len(missing))
for s,(b,ci,body) in sorted(missing.items(), key=lambda kv: kv[1][1]):
    first = [l for l in body.split("\n") if l.startswith(("Speaker:","Episode:"))]
    print(s, b, ci, "|", "; ".join(first))
EOF
python3 /tmp/check_complete.py
